103	    async fn list(
104	        &self,
105	        request: ListMemoriesRequest,
106	    ) -> Result<ListMemoriesResponse, MemoriesBackendError> {
107	        let max_results = request.max_results.min(MAX_LIST_RESULTS);
108	        let start = self.resolve_scoped_path(request.path.as_deref()).await?;
109	        let start_index = match request.cursor.as_deref() {
110	            Some(cursor) => cursor.parse::<usize>().map_err(|_| {
111	                MemoriesBackendError::invalid_cursor(cursor, "must be a non-negative integer")
112	            })?,
113	            None => 0,
114	        };
115	        let Some(metadata) = Self::metadata_or_none(&start).await? else {
116	            return Err(MemoriesBackendError::NotFound {
117	                path: request.path.unwrap_or_default(),
118	            });
119	        };
120	        reject_symlink(&display_relative_path(&self.root, &start), &metadata)?;
121	
122	        let mut entries = if metadata.is_file() {
123	            vec![MemoryEntry {
124	                path: display_relative_path(&self.root, &start),
125	                entry_type: MemoryEntryType::File,
126	            }]
127	        } else if metadata.is_dir() {
128	            let mut entries = Vec::new();
129	            for path in read_sorted_dir_paths(&start).await? {
130	                if is_hidden_path(&path) {
131	                    continue;
132	                }
133	                let Some(metadata) = Self::metadata_or_none(&path).await? else {
134	                    continue;
135	                };
136	                if metadata.file_type().is_symlink() {
137	                    continue;
138	                }
139	
140	                let entry_type = if metadata.is_dir() {
141	                    MemoryEntryType::Directory
142	                } else if metadata.is_file() {
143	                    MemoryEntryType::File
144	                } else {
145	                    continue;
146	                };
147	                entries.push(MemoryEntry {
148	                    path: display_relative_path(&self.root, &path),
149	                    entry_type,
150	                });
151	            }
152	            entries
153	        } else {
154	            Vec::new()
155	        };
156	        if start_index > entries.len() {
157	            return Err(MemoriesBackendError::invalid_cursor(
158	                start_index.to_string(),
159	                "exceeds result count",
160	            ));
161	        }
162	
163	        let end_index = start_index.saturating_add(max_results).min(entries.len());
164	        let next_cursor = (end_index < entries.len()).then(|| end_index.to_string());
165	        let truncated = next_cursor.is_some();
166	        Ok(ListMemoriesResponse {
167	            path: request.path,
168	            entries: entries.drain(start_index..end_index).collect(),
169	            next_cursor,
170	            truncated,
171	        })
172	    }
