91	    fn get_info(&self) -> ServerInfo {
92	        ServerInfo {
93	            instructions: Some(
94	                "Use these tools to list, read, and search Codex memory files.".to_string(),
95	            ),
96	            capabilities: ServerCapabilities::builder().enable_tools().build(),
97	            ..ServerInfo::default()
98	        }
99	    }
100	
101	    fn list_tools(
102	        &self,
103	        _request: Option<PaginatedRequestParams>,
104	        _context: rmcp::service::RequestContext<rmcp::service::RoleServer>,
105	    ) -> impl std::future::Future<Output = Result<ListToolsResult, McpError>> + Send + '_ {
106	        let tools = Arc::clone(&self.tools);
107	        async move {
108	            Ok(ListToolsResult {
109	                tools: (*tools).clone(),
110	                next_cursor: None,
111	                meta: None,
112	            })
113	        }
114	    }
115	
116	    async fn call_tool(
117	        &self,
118	        request: CallToolRequestParams,
119	        _context: rmcp::service::RequestContext<rmcp::service::RoleServer>,
120	    ) -> Result<CallToolResult, McpError> {
121	        let value = serde_json::Value::Object(
122	            request
123	                .arguments
124	                .unwrap_or_default()
125	                .into_iter()
126	                .collect::<serde_json::Map<String, serde_json::Value>>(),
127	        );
128	        let structured_content = match request.name.as_ref() {
129	            LIST_TOOL_NAME => {
130	                let args: ListArgs = parse_args(value)?;
131	                json!(
132	                    self.backend
133	                        .list(ListMemoriesRequest {
134	                            path: args.path,
135	                            cursor: args.cursor,
136	                            max_results: clamp_max_results(
137	                                args.max_results,
138	                                DEFAULT_LIST_MAX_RESULTS,
139	                                MAX_LIST_RESULTS,
140	                            ),
141	                        })
142	                        .await
143	                        .map_err(backend_error_to_mcp)?
144	                )
145	            }
146	            READ_TOOL_NAME => {
147	                let args: ReadArgs = parse_args(value)?;
148	                json!(
149	                    self.backend
150	                        .read(ReadMemoryRequest {
151	                            path: args.path,
152	                            line_offset: args.line_offset.unwrap_or(1),
153	                            max_lines: args.max_lines,
154	                            max_tokens: DEFAULT_READ_MAX_TOKENS,
155	                        })
156	                        .await
157	                        .map_err(backend_error_to_mcp)?
158	                )
159	            }
160	            SEARCH_TOOL_NAME => {
161	                let args: SearchArgs = parse_args(value)?;
162	                let request = args.into_request();
163	                json!(
164	                    self.backend
165	                        .search(request)
166	                        .await
167	                        .map_err(backend_error_to_mcp)?
168	                )
169	            }
170	            other => {
171	                return Err(McpError::invalid_params(
172	                    format!("unknown tool: {other}"),
173	                    None,
174	                ));
175	            }
176	        };
177	
178	        Ok(CallToolResult {
179	            content: vec![Content::text(structured_content.to_string())],
180	            structured_content: Some(structured_content),
181	            is_error: Some(false),
182	            meta: None,
183	        })
184	    }
185	}
