187	pub async fn run_stdio_server(codex_home: &AbsolutePathBuf) -> anyhow::Result<()> {
188	    let backend = LocalMemoriesBackend::from_codex_home(codex_home);
189	    tokio::fs::create_dir_all(backend.root())
190	        .await
191	        .with_context(|| format!("create memories root at {}", backend.root().display()))?;
192	    MemoriesMcpServer::new(backend)
193	        .serve((tokio::io::stdin(), tokio::io::stdout()))
194	        .await?
195	        .waiting()
196	        .await?;
197	    Ok(())
198	}
